const crypto = require('crypto');
const headers = Object.fromEntries(Object.entries($json.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]));
const actual = Buffer.from(String(headers.authorization ?? ''), 'utf8');
const expectedSecret = String($env.FORGEJO_WEBHOOK_CREDENTIAL ?? '');
const expected = Buffer.from('Bearer ' + expectedSecret, 'utf8');
const authenticated = expectedSecret.length > 0 && actual.length === expected.length && crypto.timingSafeEqual(actual, expected);
if (!authenticated) throw new Error('Unauthorized Forgejo webhook');
return { json: $json };

const incoming = $json;
const body = incoming.body ?? {};
const headers = Object.fromEntries(Object.entries(incoming.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]));
const eventHeader = String(headers['x-forgejo-event'] ?? headers['x-gitea-event'] ?? '').toLowerCase();
const deliveryId = String(headers['x-forgejo-delivery'] ?? headers['x-gitea-delivery'] ?? body.delivery_id ?? $execution.id);
const actionRaw = String(body.action ?? '').toLowerCase();
const run = body.run ?? {};
const parseObject = (value) => {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || value.length === 0) return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
};
const eventPayload = parseObject(run.event_payload);
const repository = body.repository ?? run.repository ?? eventPayload.repository ?? {};
const repo = String(repository.full_name ?? repository.name ?? 'unknown/unknown');
const actor = String(body.pusher?.username ?? body.pusher?.login ?? body.sender?.login ?? body.sender?.username ?? eventPayload.pusher?.username ?? eventPayload.pusher?.login ?? eventPayload.sender?.login ?? eventPayload.sender?.username ?? run.trigger_user?.login ?? run.trigger_user?.username ?? 'unknown');
const pullRequest = body.pull_request ?? {};
let eventType = 'unsupported';
if (body.executionMode === 'test' || incoming.executionMode === 'test') eventType = 'test';
else if (eventHeader.includes('pull_request') || body.pull_request) eventType = 'pull_request';
else if (eventHeader === 'push' || body.head_commit || Array.isArray(body.commits)) eventType = 'push';
else if (eventHeader.includes('package') || body.package) eventType = 'package';
else if (eventHeader.includes('release') || body.release) eventType = 'release';
else if (eventHeader.includes('workflow') || eventHeader.includes('action') || body.run) eventType = 'action';
const ref = String(eventPayload.ref ?? run.ref ?? body.ref ?? '');
const workflowId = String(run.workflow_id ?? run.workflow_name ?? 'Forgejo Actions');
const workflowName = String(run.workflow_name ?? run.workflow_id ?? 'Forgejo Actions');
const runTitle = String(run.title ?? '');
const runId = String(run.id ?? run.run_number ?? run.commit_sha ?? body.after ?? body.head_commit?.id ?? body.package?.id ?? body.release?.id ?? deliveryId);
const statusCandidate = String(run.conclusion ?? run.status ?? actionRaw).toLowerCase();
let actionStatus = 'unknown';
if (['failure', 'failed', 'error', 'cancelled', 'canceled'].includes(actionRaw) || ['failure', 'failed', 'error', 'cancelled', 'canceled'].includes(statusCandidate)) actionStatus = 'failure';
else if (['recovered', 'recovery'].includes(actionRaw) || ['recovered', 'recovery'].includes(statusCandidate)) actionStatus = 'recovery';
else if (['success', 'successful'].includes(actionRaw) || ['success', 'successful'].includes(statusCandidate)) actionStatus = 'success';
const packageInfo = body.package ?? {};
const releaseInfo = body.release ?? {};
const prNumber = String(pullRequest.number ?? pullRequest.index ?? body.number ?? '');
const prHeadSha = String(pullRequest.head?.sha ?? pullRequest.head?.id ?? '');
const objectId = eventType === 'pull_request'
  ? [prNumber || deliveryId, prHeadSha || deliveryId].join(':')
  : eventType === 'push'
    ? String(body.after ?? body.head_commit?.id ?? body.compare_url ?? deliveryId)
    : eventType === 'package'
      ? String(packageInfo.id ?? ((packageInfo.name ?? 'package') + '@' + (packageInfo.version ?? 'unknown')))
      : eventType === 'release'
        ? String(releaseInfo.id ?? releaseInfo.tag_name ?? releaseInfo.name ?? deliveryId)
        : runId;
const eventKey = [repo, eventType, objectId, eventType === 'package' || eventType === 'release' ? actionRaw : ''].join('::');
const stateKey = eventType === 'action'
  ? [repo, 'action', workflowId, ref].join('::')
  : eventKey;
const prActionSupported = ['opened', 'synchronize', 'synchronized', 'reopened'].includes(actionRaw);
const supported = ['test', 'push', 'package', 'release'].includes(eventType) || (eventType === 'pull_request' && prActionSupported) || (eventType === 'action' && actionStatus !== 'unknown');
const commits = Array.isArray(body.commits) ? body.commits.slice(0, 10).map((commit) => ({
  id: String(commit.id ?? '').slice(0, 7),
  message: String(commit.message ?? '').split('\n')[0],
  url: String(commit.url ?? ''),
})) : [];
return { json: {
  SUPPORTED: supported,
  EVENT_TYPE: eventType,
  EVENT_HEADER: eventHeader,
  EVENT_KEY: eventKey,
  STATE_KEY: stateKey,
  DELIVERY_ID: deliveryId,
  ACTION_RAW: actionRaw,
  ACTION_STATUS: actionStatus,
  REPO: repo,
  REPO_URL: String(repository.html_url ?? repository.url ?? ''),
  ACTOR: actor,
  REF: ref,
  SHA: String(run.commit_sha ?? body.after ?? body.head_commit?.id ?? prHeadSha),
  RUN_ID: runId,
  RUN_URL: String(run.html_url ?? run.url ?? ''),
  RUN_TITLE: runTitle,
  WORKFLOW_ID: workflowId,
  WORKFLOW_NAME: workflowName,
  TRIGGER_EVENT: String(run.trigger_event ?? run.event ?? ''),
  PUSH_COMPARE_URL: String(body.compare_url ?? ''),
  PUSH_COMMITS: commits,
  PUSH_COMMIT_COUNT: Array.isArray(body.commits) ? body.commits.length : 0,
  PACKAGE_NAME: String(packageInfo.name ?? ''),
  PACKAGE_VERSION: String(packageInfo.version ?? ''),
  PACKAGE_URL: String(packageInfo.html_url ?? packageInfo.url ?? ''),
  RELEASE_NAME: String(releaseInfo.name ?? ''),
  RELEASE_TAG: String(releaseInfo.tag_name ?? ''),
  RELEASE_URL: String(releaseInfo.html_url ?? releaseInfo.url ?? ''),
  PR_NUMBER: prNumber,
  PR_TITLE: String(pullRequest.title ?? ''),
  PR_BODY: String(pullRequest.body ?? ''),
  PR_URL: String(pullRequest.html_url ?? pullRequest.url ?? ''),
  PR_HEAD_REF: String(pullRequest.head?.ref ?? pullRequest.head?.label ?? ''),
  PR_HEAD_SHA: prHeadSha,
  PR_BASE_REF: String(pullRequest.base?.ref ?? pullRequest.base?.label ?? ''),
  IS_RENOVATE_PR: eventType === 'pull_request' && prActionSupported && ['infrastructure/infra', 'infrastructure/infra-private'].includes(repo) && pullRequest.base?.ref === 'main' && actor === 'renovate',
} };

const current = $('Normalize Forgejo Event').first().json;
const previous = $json ?? {};
const duplicateDelivery = Boolean(previous.LAST_DELIVERY_ID) && String(previous.LAST_DELIVERY_ID) === String(current.DELIVERY_ID);
const duplicateObject = current.EVENT_TYPE !== 'action' && current.EVENT_TYPE !== 'test' && Boolean(previous.STATE_KEY);
let notifyStatus = current.ACTION_STATUS;
if (current.EVENT_TYPE === 'action' && current.ACTION_STATUS === 'success' && previous.LAST_STATUS === 'failure') notifyStatus = 'recovery';
if (current.ACTION_STATUS === 'recovery') notifyStatus = 'recovery';
const shouldNotify = current.EVENT_TYPE === 'test' ? true : !(duplicateDelivery || duplicateObject);
const storedStatus = current.EVENT_TYPE === 'action' ? (notifyStatus === 'recovery' ? 'success' : current.ACTION_STATUS) : current.EVENT_TYPE;
const icon = notifyStatus === 'failure' ? '❌' : notifyStatus === 'recovery' ? '♻️' : '✅';
const actor = current.ACTOR === 'unknown' ? 'unknown' : '@' + current.ACTOR + ':beaco.works';
let message = '';
if (current.EVENT_TYPE === 'test') {
  message = '## ✅ Forgejo webhook 测试成功\n\n事件标准化、状态表与 Matrix 通知链路可用。';
} else if (current.EVENT_TYPE === 'pull_request') {
  message = '## 🤖 ' + current.REPO + ' Renovate PR #' + current.PR_NUMBER + '\n\n| 项目 | 内容 |\n| :--- | :--- |\n| 动作 | ' + current.ACTION_RAW + ' |\n| 标题 | ' + current.PR_TITLE + ' |\n| 分支 | ' + current.PR_HEAD_REF + ' → ' + current.PR_BASE_REF + ' |\n| SHA | ' + current.PR_HEAD_SHA + ' |\n| 发起人 | ' + actor + ' |\n| 链接 | [查看 PR](' + current.PR_URL + ') |';
} else if (current.EVENT_TYPE === 'push') {
  const commitLines = current.PUSH_COMMITS.map((commit) => '| ' + commit.id + ' | [' + commit.message + '](' + commit.url + ') |').join('\n');
  const remainder = current.PUSH_COMMIT_COUNT > current.PUSH_COMMITS.length ? '\n\n另有 ' + (current.PUSH_COMMIT_COUNT - current.PUSH_COMMITS.length) + ' 个提交未展开。' : '';
  message = '## 🚀 ' + current.REPO + ' 检测到推送\n\n| 项目 | 内容 |\n| :--- | :--- |\n| 推送人 | ' + actor + ' |\n| 分支 | ' + current.REF + ' |\n| Diff | [查看差异](' + current.PUSH_COMPARE_URL + ') |\n\n| SHA | 提交 |\n| :--- | :--- |\n' + commitLines + remainder;
} else if (current.EVENT_TYPE === 'package') {
  message = '## 📦 ' + current.REPO + ' 软件包事件\n\n| 项目 | 内容 |\n| :--- | :--- |\n| 动作 | ' + current.ACTION_RAW + ' |\n| 软件包 | ' + current.PACKAGE_NAME + ' |\n| 版本 | ' + current.PACKAGE_VERSION + ' |\n| 操作人 | ' + actor + ' |\n| 链接 | [查看软件包](' + current.PACKAGE_URL + ') |';
} else if (current.EVENT_TYPE === 'release') {
  message = '## 🏷️ ' + current.REPO + ' 版本发布事件\n\n| 项目 | 内容 |\n| :--- | :--- |\n| 动作 | ' + current.ACTION_RAW + ' |\n| 版本 | ' + (current.RELEASE_TAG || current.RELEASE_NAME) + ' |\n| 操作人 | ' + actor + ' |\n| 链接 | [查看版本](' + current.RELEASE_URL + ') |';
} else {
  const label = notifyStatus === 'failure' ? '失败' : notifyStatus === 'recovery' ? '恢复' : '成功';
  const rows = [
    '| 工作流 | ' + current.WORKFLOW_NAME + ' |',
    current.RUN_TITLE ? '| 运行标题 | ' + current.RUN_TITLE + ' |' : '',
    '| 状态 | ' + label + ' |',
    '| 触发类型 | ' + current.TRIGGER_EVENT + ' |',
    '| 来源 | ' + current.REF + ' |',
    '| SHA | ' + current.SHA + ' |',
    current.RUN_URL ? '| 执行 | [查看运行](' + current.RUN_URL + ') |' : '',
    '| 发起人 | ' + actor + ' |',
  ].filter(Boolean).join('\n');
  message = '## ' + icon + ' ' + current.REPO + ' Action ' + label + '\n\n| 项目 | 内容 |\n| :--- | :--- |\n' + rows;
}
const successfulAction = current.EVENT_TYPE === 'action' && ['success', 'recovery'].includes(notifyStatus);
const releaseWorkflow = current.WORKFLOW_ID === 'build-and-push.yaml';
const releaseTagRun = releaseWorkflow && current.REPO === 'infrastructure/infra-private' && current.REF.startsWith('refs/tags/');
return { json: {
  ...current,
  SHOULD_NOTIFY: shouldNotify,
  NOTIFY_STATUS: notifyStatus,
  STORED_STATUS: storedStatus,
  NEEDS_APPROVAL: successfulAction && releaseWorkflow && current.REPO === 'infrastructure/infra-private' && current.TRIGGER_EVENT === 'workflow_dispatch',
  COMPLETES_RELEASE: successfulAction && releaseTagRun,
  MESSAGE_MARKDOWN: message,
  UPDATED_AT: $now.toISO(),
  RELEASE_UUID: $execution.id + '-' + current.SHA,
  RELEASE_TAG_SUGGESTION: $now.setZone('Asia/Shanghai').toFormat('yyyyMMdd-HHmm'),
} };

const event = $('Decide Event Transition').first().json;
const url = 'https://automaton.beaco.works/form/1490962f-d8d5-449a-a6d8-3f16ce29ffe2?uuid=' + encodeURIComponent(event.RELEASE_UUID) + '&tag=' + encodeURIComponent(event.RELEASE_TAG_SUGGESTION);
return { json: { ...event, MESSAGE_MARKDOWN: event.MESSAGE_MARKDOWN + '\n\ninfra-private 手动构建成功，可以发版：[进入审批](' + url + ')' } };

const crypto = require('crypto');
const event = $('Decide Event Transition').first().json;
const repo = String(event.REPO);
const prNumber = Number(event.PR_NUMBER);
const headSha = String(event.PR_HEAD_SHA).toLowerCase();
const secret = String($env.REVIEW_CAPABILITY_SECRET ?? '');
if (!secret || !['infrastructure/infra', 'infrastructure/infra-private'].includes(repo) || !Number.isInteger(prNumber) || prNumber <= 0 || !/^[0-9a-f]{40}$/.test(headSha)) throw new Error('Cannot create review capability');
const iat = Math.floor(Date.now() / 1000);
const claims = { v: 1, repo, pr_number: prNumber, head_sha: headSha, iat, exp: iat + 86400, jti: crypto.randomUUID() };
const encoded = Buffer.from(JSON.stringify(claims), 'utf8').toString('base64url');
const signature = crypto.createHmac('sha256', secret).update(encoded).digest('base64url');
return { json: { ...event, REVIEW_CAPABILITY: encoded + '.' + signature } };

const crypto = require('crypto');
const body = $json.body ?? {};
const capability = String(body.capability ?? '');
const verdict = String(body.verdict ?? '').toLowerCase();
const summary = String(body.summary ?? '').trim();
const evidenceUrl = String(body.evidence_url ?? '').trim();
const secret = String($env.REVIEW_CAPABILITY_SECRET ?? '');
let claims = {};
let signatureValid = false;
try {
  const parts = capability.split('.');
  if (secret && parts.length === 2 && parts.every(Boolean)) {
    const actual = Buffer.from(parts[1], 'base64url');
    const expected = crypto.createHmac('sha256', secret).update(parts[0]).digest();
    signatureValid = actual.length === expected.length && crypto.timingSafeEqual(actual, expected);
    if (signatureValid) claims = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
  }
} catch {
  signatureValid = false;
  claims = {};
}
const now = Math.floor(Date.now() / 1000);
const repo = String(claims.repo ?? '');
const prNumber = claims.pr_number;
const headSha = String(claims.head_sha ?? '').toLowerCase();
const claimsValid = signatureValid
  && claims.v === 1
  && ['infrastructure/infra', 'infrastructure/infra-private'].includes(repo)
  && Number.isInteger(prNumber) && prNumber > 0
  && /^[0-9a-f]{40}$/.test(headSha)
  && Number.isInteger(claims.iat) && Number.isInteger(claims.exp)
  && claims.iat <= now && claims.exp > now
  && claims.exp - claims.iat === 86400
  && typeof claims.jti === 'string' && claims.jti.length > 0;
const fieldsValid = ['approve', 'reject'].includes(verdict)
  && summary.length > 0 && summary.length <= 10000
  && (evidenceUrl === '' || /^https:\/\/[^\s]+$/.test(evidenceUrl));
return { json: { REVIEW_VALID: claimsValid && fieldsValid, REPO: repo, PR_NUMBER: prNumber, HEAD_SHA: headSha, VERDICT: verdict, SUMMARY: summary, EVIDENCE_URL: evidenceUrl } };

const review = $('Validate Multica Review').first().json;
const response = $json ?? {};
const pr = response.body ?? {};
const matches = response.statusCode === 200
  && pr.state === 'open'
  && pr.base?.ref === 'main'
  && String(pr.head?.sha ?? '').toLowerCase() === review.HEAD_SHA
  && String(pr.user?.login ?? pr.user?.username ?? '') === 'renovate';
return { json: { ...review, PR_MATCHES: matches } };

const statusCode = Number($json.statusCode ?? 0);
const message = String($json.body?.message ?? $json.statusMessage ?? 'Forgejo merge request failed').slice(0, 500);
return { json: { MERGE_OK: statusCode === 200, RESPONSE_CODE: [409, 422].includes(statusCode) ? 409 : 502, FORGEJO_STATUS: statusCode, ERROR_MESSAGE: message } };
